Object.assign(window.STUDY_EXAMS,{"dta301_fa24":{"title":"FA 2024 · FE — 58 câu luyện","short":"FA 2024 · FE","storageKey":"dta301_unified_fa24_60_v2","legacyKey":"dta301_unified_fa24_60_v1","notice":"58 câu đã có đáp án để luyện tập và thi thử. 2 câu còn cần làm rõ được chuyển sang danh sách Câu cần xác minh. Giữ số câu gốc, giải thích, nguồn và mẹo nhớ.","questions":[{"id":2,"stem":"Which of the following are attributes stand out as defining Big Data characteristics?","options":["Huge volume","Complexity of type and structure","Speed of new data creation and growth","All of the others"],"image":"assets/dta301/fa24/02.webp","suppliedKey":null,"multiple":false,"correct":[3],"chapter":1,"sourceTerm":"volume","detail":"Ba đặc trưng cốt lõi là Volume, Variety và Velocity.","trick":"3V: Lượng – Loại – Tốc độ.","why":["Volume đúng nhưng chỉ là một đặc trưng.","Độ đa dạng kiểu/cấu trúc tương ứng Variety, chưa đủ cả ba.","Tốc độ tạo dữ liệu tương ứng Velocity, chưa đủ cả ba.","Bao gồm đủ ba đặc trưng A, B và C."],"caution":"","topic":"Big Data và vai trò","gradable":true,"keyChanged":false,"bookPage":2,"pdfPage":22,"reference":"Sách chương 1, trang 2 (PDF trang 22) · Slide chương 1, slide 5","slideNumbers":[5],"keywords":["defining","Big Data characteristics"]},{"id":3,"stem":"Which of roles of the new Big Data ecosystem is technically savvy, with strong analytical skills?","options":["Deep Analytical Talent","Data Savvy Professionals","Technology and Data Enablers","Data Researchers"],"image":"assets/dta301/fa24/03.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":1,"sourceTerm":"Deep Analytical Talent","detail":"Deep Analytical Talent có chuyên môn kỹ thuật và phân tích sâu để xử lý dữ liệu và xây mô hình.","trick":"Deep = đào sâu mô hình; Savvy = hỏi đúng; Enabler = dựng nền.","why":["Đúng mô tả nhóm có kỹ năng phân tích sâu.","Nhóm này hiểu nghiệp vụ và đặt câu hỏi, ít chuyên sâu kỹ thuật hơn.","Nhóm này hỗ trợ hạ tầng và môi trường dữ liệu.","Không phải tên một trong ba nhóm trong mô hình hệ sinh thái của sách."],"caution":"","topic":"Big Data và vai trò","gradable":true,"keyChanged":false,"bookPage":19,"pdfPage":39,"reference":"Sách chương 1, trang 19 (PDF trang 39) · Slides chương 1","slideNumbers":[],"keywords":["roles","technically savvy","strong analytical skills"]},{"id":4,"stem":"Which of the following represents people providing technical expertise to support analytical projects, such as provisioning and administrating analytical sandboxes, and managing large-scale data architectures that enable widespread analytics within companies and other organizations?","options":["Data Savvy Professionals","Technology and Data Enablers","Deep Analytical Talent","Data Researchers"],"image":"assets/dta301/fa24/04.webp","suppliedKey":null,"multiple":false,"correct":[1],"chapter":1,"sourceTerm":"Technology and Data Enablers","detail":"Nhóm Technology and Data Enablers cung cấp sandbox, quản trị kiến trúc và hạ tầng phục vụ phân tích.","trick":"Enable = tạo điều kiện, dựng hạ tầng.","why":["Thiên về nghiệp vụ và đặt câu hỏi phân tích.","Đúng vai trò hỗ trợ kỹ thuật và kiến trúc dữ liệu.","Tập trung xây và áp dụng mô hình phân tích.","Không phải nhóm vai trò được định nghĩa trong mô hình ba nhóm."],"caution":"","topic":"Big Data và vai trò","gradable":true,"keyChanged":false,"bookPage":20,"pdfPage":40,"reference":"Sách chương 1, trang 20 (PDF trang 40) · Slides chương 1","slideNumbers":[],"keywords":["technical expertise","analytical sandboxes","data architectures"]},{"id":5,"stem":"Who has less technical depth but has a basic knowledge of statistics or machine learning and can define key questions that can be answered using advanced analytics?","options":["Data Savvy Professionals","Technology and Data Enablers","Deep Analytical Talent","Database Administrators."],"image":"assets/dta301/fa24/05.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":1,"sourceTerm":"Data Savvy Professionals","detail":"Data Savvy Professionals đủ hiểu thống kê/ML để xác định câu hỏi nghiệp vụ, nhưng có độ sâu kỹ thuật thấp hơn nhóm phân tích chuyên sâu.","trick":"Savvy biết hỏi “doanh nghiệp cần gì?”.","why":["Khớp mô tả hiểu dữ liệu để đặt câu hỏi.","Cung cấp hạ tầng và công nghệ.","Có độ sâu kỹ thuật và phân tích cao.","DBA tập trung quản trị cơ sở dữ liệu, không phải nhóm vai trò được hỏi."],"caution":"","topic":"Big Data và vai trò","gradable":true,"keyChanged":false,"bookPage":20,"pdfPage":40,"reference":"Sách chương 1, trang 20 (PDF trang 40) · Slides chương 1","slideNumbers":[],"keywords":["less technical depth","define key questions"]},{"id":6,"stem":"Data science teams would rather keep more data than too little data for the analysis. The questions for the data conditioning step that the team should answer include these, except:","options":["What are the data sources? What are the target fields?","How clean is the data?","How consistent are the contents and files?","What is the programming language used for data processing?"],"image":"assets/dta301/fa24/06.webp","suppliedKey":null,"multiple":false,"correct":[3],"chapter":2,"sourceTerm":"Data Conditioning","detail":"Data conditioning xem xét nguồn, trường mục tiêu, độ sạch và tính nhất quán; chọn ngôn ngữ không thuộc danh sách câu hỏi kiểm tra chất lượng dữ liệu.","trick":"Condition = tình trạng dữ liệu; language = công cụ.","why":["Nguồn dữ liệu và trường mục tiêu là câu hỏi conditioning.","Độ sạch là nội dung conditioning.","Tính nhất quán cũng là nội dung conditioning.","Đây là lựa chọn công cụ triển khai, là ngoại lệ của danh sách được hỏi."],"caution":"","topic":"Data Analytics Lifecycle","gradable":true,"keyChanged":false,"bookPage":40,"pdfPage":60,"reference":"Sách chương 2, trang 40 (PDF trang 60) · Slide chương 2, slide 19","slideNumbers":[19],"keywords":["data conditioning","except"]},{"id":8,"stem":"In which of the following phase, the team should identify key findings, quantify the business value, and develop a narrative to summarize and convey findings to stakeholders?","options":["Data discovery","Data preparation","Model building","Model planning","Communicate result"],"image":"assets/dta301/fa24/08.webp","suppliedKey":null,"multiple":false,"correct":[4],"chapter":2,"sourceTerm":"Communicate Results","detail":"Phase 5 tổng hợp phát hiện, định lượng giá trị kinh doanh và xây câu chuyện truyền đạt cho stakeholders.","trick":"Kết quả + giá trị + kể chuyện = Phase 5.","why":["Discovery xác định bài toán và giả thuyết ban đầu.","Data Preparation chuẩn bị dữ liệu.","Model Building huấn luyện và đánh giá mô hình.","Model Planning chọn phương pháp và kế hoạch mô hình.","Communicate Results đúng nhiệm vụ truyền đạt phát hiện."],"caution":"","topic":"Data Analytics Lifecycle","gradable":true,"keyChanged":false,"bookPage":49,"pdfPage":69,"reference":"Sách chương 2, trang 49 (PDF trang 69) · Slide chương 2, slide 27","slideNumbers":[27],"keywords":["identify key findings","business value","convey findings"]},{"id":9,"stem":"A part of ____ involves deciding which aspects of particular datasets will be useful to analyze in later steps.","options":["Data conditioning","Performing ETLT","Developing Initial Hypotheses","Data analysis"],"image":"assets/dta301/fa24/09.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":2,"sourceTerm":"particular datasets","detail":"Lựa chọn phần dữ liệu giữ lại, biến đổi hay bỏ đi là quyết định trong Data Conditioning.","trick":"Giữ – sửa – bỏ dữ liệu = conditioning.","why":["Đúng phần quyết định dữ liệu nào hữu ích cho phân tích sau.","ETLT nói về luồng extract, transform, load, transform; không phải tên bước của đoạn trích.","Initial Hypotheses là tạo giả thuyết cần kiểm tra ở Discovery.","Data analysis quá chung, không phải bước cụ thể được sách nêu."],"caution":"","topic":"Data Analytics Lifecycle","gradable":true,"keyChanged":false,"bookPage":40,"pdfPage":60,"reference":"Sách chương 2, trang 40 (PDF trang 60) · Slides chương 2","slideNumbers":[],"keywords":["particular datasets","useful to analyze in later steps"]},{"id":10,"stem":"The data-conditioning step is usually performed only by the following member, except:","options":["The data owners","A data engineer","A database administrator","A programmer"],"image":"assets/dta301/fa24/10.webp","suppliedKey":null,"multiple":false,"correct":[3],"chapter":2,"sourceTerm":"data-conditioning step","detail":"Theo danh sách trong sách, conditioning thường gắn với IT, data owners, DBA và data engineer. Programmer không được liệt kê thành vai trò riêng trong câu này.","trick":"Owner – DBA – Engineer; vẫn cần Data Scientist tham gia.","why":["Data owners được sách liệt kê.","Data engineer được sách liệt kê.","DBA được sách liệt kê.","Không được liệt kê riêng trong nhóm vai trò này."],"caution":"Đây là câu nhận diện danh sách của sách. Lập trình viên vẫn có thể làm conditioning; từ “only” trong câu không nên hiểu là cấm vai trò khác. Sách nhấn mạnh phải có Data Scientist tham gia.","topic":"Data Analytics Lifecycle","gradable":true,"keyChanged":false,"bookPage":40,"pdfPage":60,"reference":"Sách chương 2, trang 40 (PDF trang 60) · Slides chương 2","slideNumbers":[],"keywords":["data-conditioning","member","except"]},{"id":11,"stem":"Which of the followings is correct statement used to add an additional column to dataset in R?","options":["sales%per_order <- sales$sales_total/sales$num_of_orders","sales+per_order <- sales$sales_total/sales$num_of_orders","addcol(per_order) < sales$sales_total/sales$num_of_orders","sales$per_order <- sales$sales_total/sales$num_of_orders"],"image":"assets/dta301/fa24/11.webp","suppliedKey":null,"multiple":false,"correct":[3],"chapter":3,"sourceTerm":"per_order","detail":"Dùng data_frame$tên_cột <- biểu_thức để thêm cột. Ở đây lấy tổng doanh thu chia số đơn.","trick":"Dấu $ chọn cột; <- gán dữ liệu.","why":["% không phải toán tử truy cập cột như $.","+ là phép cộng, không dùng để tạo cột theo cú pháp này.","addcol(per_order) không phải cú pháp thêm cột base R, và < không phải <-.","Cú pháp truy cập cột và phép gán đều đúng."],"caution":"","topic":"R và thống kê cơ bản","gradable":true,"keyChanged":false,"bookPage":70,"pdfPage":90,"reference":"Sách chương 3, trang 70 (PDF trang 90) · Slides chương 3","slideNumbers":[],"keywords":["add an additional column","R"]},{"id":12,"stem":"The expected defaults for headers, column separators, and decimal point notations of read.table() function are ____.","options":["header=FALSE, sep=\"\", dec=\".\"","header=TRUE, sep=\",\", dec=\".\"","header=TRUE, sep=\";\", dec=\".\"","header=TRUE, sep=\"\\t\", dec=\".\""],"image":"assets/dta301/fa24/12.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":3,"sourceTerm":"read.table","detail":"read.table mặc định header=FALSE, sep=\"\" (whitespace), dec=\".\".","trick":"TABLE trần: chưa header, cách trắng, chấm.","why":["Đúng bộ mặc định của read.table.","header=TRUE và dấu phẩy là kiểu read.csv.","Header và separator không đúng mặc định read.table.","Tab và header=TRUE là kiểu read.delim."],"caution":"","topic":"R và thống kê cơ bản","gradable":true,"keyChanged":false,"bookPage":69,"pdfPage":89,"reference":"Sách chương 3, trang 69 (PDF trang 89) · Slide chương 3, slide 15","slideNumbers":[15],"keywords":["defaults","read.table()"]},{"id":13,"stem":"The expected defaults for headers, column separators, and decimal point notations of read.delim() function are ____.","options":["header=FALSE, sep=\"\", dec=\".\"","header=TRUE, sep=\",\", dec=\".\"","header=TRUE, sep=\";\", dec=\",\"","header=TRUE, sep=\"\\t\", dec=\".\"","header=TRUE, sep=\"\\t\", dec=\",\""],"image":"assets/dta301/fa24/13.webp","suppliedKey":null,"multiple":false,"correct":[3],"chapter":3,"sourceTerm":"read.delim","detail":"read.delim mặc định header=TRUE, sep=\"\\t\", dec=\".\".","trick":"DELIM = TAB; bản thường dùng chấm.","why":["Đây là mặc định read.table.","Dấu phẩy là kiểu read.csv.","Dấu chấm phẩy và dấu phẩy thập phân là kiểu read.csv2.","Đúng cả header, tab và dấu chấm thập phân.","Đây là read.delim2 vì dùng dấu phẩy thập phân."],"caution":"","topic":"R và thống kê cơ bản","gradable":true,"keyChanged":false,"bookPage":69,"pdfPage":89,"reference":"Sách chương 3, trang 69 (PDF trang 89) · Slide chương 3, slide 15, 16","slideNumbers":[15,16],"keywords":["defaults","read.delim()"]},{"id":14,"stem":"The expected defaults for headers, column separators, and decimal point notations of read.delim2() function are ____.","options":["header=FALSE, sep=\"\\t\", dec=\".\"","header=TRUE, sep=\",\", dec=\".\"","header=TRUE, sep=\";\", dec=\",\"","header=TRUE, sep=\"\\t\", dec=\".\"","header=TRUE, sep=\"\\t\", dec=\",\""],"image":"assets/dta301/fa24/14.webp","suppliedKey":null,"multiple":false,"correct":[4],"chapter":3,"sourceTerm":"read.delim","detail":"read.delim2 giữ header=TRUE và tab nhưng đổi dec thành dấu phẩy.","trick":"Hàm có số 2: thập phân dùng phẩy.","why":["header=FALSE và dấu chấm đều không khớp.","Dấu phẩy phân cột và dấu chấm thập phân là kiểu read.csv.","Đây là read.csv2, dùng chấm phẩy phân cột.","Đây là read.delim thông thường.","Đúng bộ mặc định read.delim2."],"caution":"","topic":"R và thống kê cơ bản","gradable":true,"keyChanged":false,"bookPage":69,"pdfPage":89,"reference":"Sách chương 3, trang 69 (PDF trang 89) · Slide chương 3, slide 15, 16","slideNumbers":[15,16],"keywords":["defaults","read.delim2()"]},{"id":15,"stem":"____ assumes that distributions of the two populations have equal but unknown variances.","options":["Student's t-test","Welch's t-test","Wilcoxon rank-sum test.","ANOVA (Analysis of variance)"],"image":"assets/dta301/fa24/15.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":3,"sourceTerm":"Student","detail":"Kiểm định t hai mẫu kiểu Student (pooled t-test) giả định hai tổng thể có phương sai bằng nhau nhưng chưa biết.","trick":"Student = Same variance; Welch = Without equal variance.","why":["Đúng giả định của Student hai mẫu gộp phương sai.","Welch cho phép hai phương sai khác nhau.","Wilcoxon dùng thứ hạng, không dựa trên giả định phương sai bằng nhau của pooled t-test.","ANOVA cũng thường giả định đồng nhất phương sai, nhưng câu trích đang định nghĩa Student hai mẫu."],"caution":"Giả định này nói về t-test Student hai mẫu độc lập, không phải mọi biến thể mang tên t-test. ANOVA cũng có giả định tương tự nên câu hỏi nhận diện tên từ đoạn sách.","topic":"R và thống kê cơ bản","gradable":true,"keyChanged":false,"bookPage":104,"pdfPage":124,"reference":"Sách chương 3, trang 104 (PDF trang 124) · Slide chương 3, slide 2, 73, 74","slideNumbers":[2,73,74],"keywords":["two populations","equal but unknown variances"]},{"id":16,"stem":"In which step of the k-means algorithm do we choose the value of k and the k initial guesses for the centroids?","options":["Step 1","Step 2","Step 3","Step 4"],"image":"assets/dta301/fa24/16.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":4,"sourceTerm":"initial guesses","detail":"Bước 1 khởi tạo số cụm k và k tâm ban đầu.","trick":"K-means: Chọn – Gán – Tính tâm – Lặp.","why":["Bước khởi tạo k và centroids.","Bước 2 tính khoảng cách, gán điểm vào cụm.","Bước 3 tính lại tâm.","Bước 4 lặp bước gán và tính tâm."],"caution":"","topic":"Clustering","gradable":true,"keyChanged":false,"bookPage":120,"pdfPage":140,"reference":"Sách chương 4, trang 120 (PDF trang 140) · Slide chương 4, slide 12","slideNumbers":[12],"keywords":["k-means","value of k","initial guesses"]},{"id":17,"stem":"k clusters can be identified in a given dataset, but we should know what value of k should be selected. Which of the followings is NOT a method to verify the k cluster? Ble","options":["We should know how much better or worse having k clusters versus k - 1 or k + 1 clusters would be in explaining the structure of the data","We use a heuristic using the Within Sum of Squares (WSS) metric is examined to determine a reasonably optimal value of k.","The value of k can be chosen based on a reasonable guess or some predefined requirement.","We should base on the size of dataset and analysis requirements."],"image":"assets/dta301/fa24/17.webp","suppliedKey":null,"multiple":false,"correct":[3],"chapter":4,"sourceTerm":"reasonable guess","detail":"Sách nêu chọn theo phỏng đoán/yêu cầu định trước và đánh giá bằng so sánh k, WSS. Không nêu kích thước dữ liệu là tiêu chí đủ để xác minh k.","trick":"Kiểm tra k bằng cấu trúc cụm/WSS, đừng lấy số dòng làm số cụm.","why":["So sánh k với k−1 và k+1 giúp đánh giá cấu trúc cụm.","WSS là tiêu chí được sách sử dụng.","Là cách khởi chọn k được sách chấp nhận khi có yêu cầu định trước.","Chỉ kích thước bộ dữ liệu không xác minh được cấu trúc hoặc k tối ưu."],"caution":"Từ “verify” chưa thật chặt: C là cách chọn ban đầu hơn là kiểm chứng. D là ngoại lệ theo danh sách trong slide 17.","topic":"Clustering","gradable":true,"keyChanged":false,"bookPage":123,"pdfPage":143,"reference":"Sách chương 4, trang 123 (PDF trang 143) · Slide chương 4, slide 17","slideNumbers":[17],"keywords":["NOT","verify the k cluster"]},{"id":18,"stem":"The formula (xc,yc) = (Σxi/m, Σyi/m) is used to ____.","options":["Compute the distance from each data point to each centroid and assign each point to the closest centroid.","Calculate the centroid (xc,yc) of the m points in a k-means cluster in two dimensions."],"image":"assets/dta301/fa24/18.webp","suppliedKey":null,"multiple":false,"correct":[1],"chapter":4,"sourceTerm":"centroid","detail":"Tâm cụm là trung bình từng tọa độ của các điểm thuộc cụm.","trick":"Σ tọa độ / số điểm = tâm cụm.","why":["Khoảng cách Euclid có căn và bình phương sai khác tọa độ.","Đúng công thức lấy trung bình x và y."],"caution":"","topic":"Clustering","gradable":true,"keyChanged":false,"bookPage":121,"pdfPage":141,"reference":"Sách chương 4, trang 121 (PDF trang 141) · Slide chương 4, slide 14","slideNumbers":[14],"keywords":["(xc,yc)","(Σxi/m, Σyi/m)"]},{"id":19,"stem":"Which of the following is NOT a steps of the k-means algorithm to find k clusters?","options":["1. Choose the value of k and the k initial guesses for the centroids.","2. Compute the distance from each data point (xi , yi ) to each centroid. Assign each point to the closest centroid. This association defines the first k clusters.","3. Compute the centroid, the center of mass, of each newly defined cluster from Step 2.","4, Repeat Steps 2 and 3 until the algorithm converges to an answer","5, Repeat until the algorithm reaches the convergence"],"image":"assets/dta301/fa24/19.webp","suppliedKey":null,"multiple":false,"correct":[4],"chapter":4,"sourceTerm":"Step 4","detail":"Thuật toán được trình bày theo 4 bước. E lặp lại ý của bước 4 chứ không phải một bước 5 độc lập.","trick":"4 bước: Chọn – Gán – Tâm – Lặp.","why":["Khởi tạo là bước 1.","Gán điểm gần tâm nhất là bước 2.","Tính tâm mới là bước 3.","Lặp đến hội tụ là bước 4.","Không có bước 5 riêng trong danh sách của sách; ý này đã nằm trong D."],"caution":"E không sai về bản chất thuật toán, chỉ thừa khi đếm các bước. Chọn E theo cấu trúc 4 bước của tài liệu.","topic":"Clustering","gradable":true,"keyChanged":false,"reference":"Sách chương 4, trang 120 (PDF trang 140) · Slide chương 4, slide 12, 13, 14, 15","slideNumbers":[12,13,14,15],"bookPage":120,"pdfPage":140,"keywords":["NOT","steps","k-means"]},{"id":20,"stem":"Is clustering the use of unsupervised techniques for grouping similar objects?","options":["True","False"],"image":"assets/dta301/fa24/20.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":4,"sourceTerm":"unsupervised","detail":"Clustering gom các đối tượng tương tự mà không dùng nhãn đích có sẵn.","trick":"Cluster = nhóm giống nhau, chưa cần nhãn.","why":["Đúng định nghĩa unsupervised clustering.","Sai vì clustering là ví dụ điển hình của học không giám sát."],"caution":"","topic":"Clustering","gradable":true,"keyChanged":false,"bookPage":117,"pdfPage":137,"reference":"Sách chương 4, trang 117 (PDF trang 137) · Slide chương 4, slide 2, 4, 27","slideNumbers":[2,4,27],"keywords":["clustering","unsupervised","grouping similar objects"]},{"id":21,"stem":"What measures how many times more often X and Y occur together than expected if they are statistically independent of each other? A Lift","options":["Lift","Leverage","Confidence","Support"],"image":"assets/dta301/fa24/21.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":5,"sourceTerm":"lift","detail":"Lift = P(X∩Y)/(P(X)P(Y)), đo số lần đồng xuất hiện so với kỳ vọng độc lập.","trick":"Lift = chia / “times more”.","why":["Đúng tỷ số thực tế so với kỳ vọng độc lập.","Leverage lấy hiệu, không phải số lần.","Confidence=P(Y|X), không chuẩn hóa theo P(Y).","Support=P(X∩Y), chưa so với độc lập."],"caution":"","topic":"Association Rules","gradable":true,"keyChanged":false,"bookPage":142,"pdfPage":162,"reference":"Sách chương 5, trang 142 (PDF trang 162) · Slide chương 5, slide 16","slideNumbers":[16],"keywords":["how many times more often","statistically independent"]},{"id":22,"stem":"What measures the difference in the probability of X and Y appearing together in the dataset compared to what would be expected if X and Y were statistically independent of each other? A Lift","options":["Lift","Leverage","Confidence","Support"],"image":"assets/dta301/fa24/22.webp","suppliedKey":null,"multiple":false,"correct":[1],"chapter":5,"sourceTerm":"leverage","detail":"Leverage = P(X∩Y) − P(X)P(Y), đo chênh lệch xác suất so với độc lập.","trick":"Leverage = trừ / “difference”.","why":["Lift là tỷ số.","Leverage đúng công thức hiệu xác suất.","Confidence là xác suất điều kiện.","Support là xác suất đồng xuất hiện thực tế."],"caution":"","topic":"Association Rules","gradable":true,"keyChanged":false,"bookPage":142,"pdfPage":162,"reference":"Sách chương 5, trang 142 (PDF trang 162) · Slide chương 5, slide 16","slideNumbers":[16],"keywords":["difference in the probability","statistically independent"]},{"id":23,"stem":"Given a large collection of transactions, in which each transaction consists of one or more items. What method can we use to go through the items being purchased to see what items are frequently bought together and to discover a list of rules that describe the purchasing behavior?","options":["Association rules","K-means","Linear regression","Decision trees"],"image":"assets/dta301/fa24/23.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":5,"sourceTerm":"transactions","detail":"Association rules phát hiện itemsets thường cùng xuất hiện và luật mua hàng.","trick":"Bought together = association rules.","why":["Đúng bài toán market basket.","K-means gom các điểm/đối tượng tương tự.","Linear regression dự đoán kết quả liên tục.","Decision tree học quy tắc dự đoán nhãn hoặc giá trị đích."],"caution":"","topic":"Association Rules","gradable":true,"keyChanged":false,"bookPage":138,"pdfPage":158,"reference":"Sách chương 5, trang 138 (PDF trang 158) · Slide chương 5, slide 3, 4, 6","slideNumbers":[3,4,6],"keywords":["transactions","frequently bought together","purchasing behavior"]},{"id":24,"stem":"If 80% of all transactions contain itemset {bread}, then the support of {bread} is ____.","options":["0.8","0.2","80","20"],"image":"assets/dta301/fa24/24.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":5,"sourceTerm":"support","detail":"Support là tỷ lệ giao dịch chứa itemset: 80/100=0.8.","trick":"Phần trăm chia 100 thành tỷ lệ.","why":["0.8 tương ứng 80%.","0.2 là tỷ lệ không chứa bread trong tình huống này.","80 là số phần trăm, không phải support dạng tỷ lệ.","20 không biểu diễn support đã cho."],"caution":"","topic":"Association Rules","gradable":true,"keyChanged":false,"bookPage":139,"pdfPage":159,"reference":"Sách chương 5, trang 139 (PDF trang 159) · Slide chương 5, slide 7","slideNumbers":[7],"keywords":["80%","support"]},{"id":25,"stem":"A frequent itemset has items that appear together often enough. The term “often enough\" is formally defined with a criterion","options":["minimum support","maximum support","support enough","threshold"],"image":"assets/dta301/fa24/25.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":5,"sourceTerm":"minimum support","detail":"Frequent itemset có support đạt ít nhất ngưỡng minimum support.","trick":"Frequent = Support ≥ MinSupport.","why":["Tên đầy đủ của tiêu chí xác định frequent itemset.","Maximum support không phải ngưỡng tối thiểu yêu cầu.","Không phải thuật ngữ chuẩn.","Threshold quá chung; tên cụ thể đúng là minimum support."],"caution":"","topic":"Association Rules","gradable":true,"keyChanged":false,"bookPage":139,"pdfPage":159,"reference":"Sách chương 5, trang 139 (PDF trang 159) · Slide chương 5, slide 8, 11, 12","slideNumbers":[8,11,12],"keywords":["frequent itemset","often enough"]},{"id":26,"stem":"Which is the value where the likelihood function is based on the parameters in the specified logistic mode?","options":["The null deviance","The residual deviance","The pseudo-R2","The different deviance"],"image":"assets/dta301/fa24/26.webp","suppliedKey":null,"multiple":false,"correct":[1],"chapter":6,"sourceTerm":"residual deviance","detail":"Residual deviance đánh giá mô hình đã lắp với các tham số của mô hình logistic được chỉ định.","trick":"Residual = mô hình đã fitted; Null = chỉ intercept.","why":["Null deviance thuộc mô hình chỉ intercept.","Đúng deviance của mô hình với các predictors đã chọn.","Pseudo-R² là thước đo suy ra từ so sánh mức phù hợp.","Không phải tên chỉ tiêu chuẩn được dùng ở đây."],"caution":"","topic":"Regression","gradable":true,"keyChanged":false,"bookPage":183,"pdfPage":203,"reference":"Sách chương 6, trang 183 (PDF trang 203) · Slide chương 6, slide 43, 46","slideNumbers":[43,46],"keywords":["likelihood function","parameters","logistic"]},{"id":27,"stem":"In logistic regression, the ____ is the value where the likelihood function is based only on the intercept term (y = β0).","options":["null deviance","residual deviance","empty deviance","different deviance"],"image":"assets/dta301/fa24/27.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":6,"sourceTerm":"null deviance","detail":"Null deviance dựa trên mô hình chỉ có intercept.","trick":"Null: chưa thêm predictor nào.","why":["Đúng chỉ tiêu cho intercept-only model.","Residual deviance thuộc mô hình có các biến giải thích đã chọn.","Không phải tên dùng trong output glm của R và tài liệu.","Không phải thuật ngữ chuẩn của output này."],"caution":"","topic":"Regression","gradable":true,"keyChanged":false,"bookPage":183,"pdfPage":203,"reference":"Sách chương 6, trang 183 (PDF trang 203) · Slide chương 6, slide 43","slideNumbers":[43],"keywords":["logistic regression","only on the intercept term"]},{"id":28,"stem":"What is a common technique to estimate the parameters in linear regression model?","options":["Ordinary Least Squares (OLS)","Minimum confidence","Leverage","Within Sum of Squares"],"image":"assets/dta301/fa24/28.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":6,"sourceTerm":"ordinary least squares","detail":"OLS ước lượng hệ số bằng cách tối thiểu tổng bình phương sai số.","trick":"Least Squares = ít tổng bình phương sai số nhất.","why":["Đúng phương pháp ước lượng tuyến tính phổ biến.","Minimum confidence là ngưỡng association rules.","Leverage là chỉ tiêu khác, không phải phương pháp ước lượng hệ số.","WSS đánh giá độ chặt cụm k-means."],"caution":"","topic":"Regression","gradable":true,"keyChanged":false,"bookPage":163,"pdfPage":183,"reference":"Sách chương 6, trang 163 (PDF trang 183) · Slide chương 6, slide 8","slideNumbers":[8],"keywords":["estimate the parameters","linear regression"]},{"id":29,"stem":"Which of the following can be used to predict the likelihood of an outcome based on the input variables?","options":["Logistic regression","Linear regression","Decision trees","Association rules"],"image":"assets/dta301/fa24/29.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":6,"sourceTerm":"likelihood of an outcome","detail":"Trong ngữ cảnh chương Regression, logistic regression mô hình hóa xác suất một kết quả nhị phân theo các biến đầu vào.","trick":"Likelihood/probability + yes/no = logistic.","why":["Lựa chọn trực tiếp nhất cho mô hình xác suất nhị phân trong chương.","Linear regression dùng cho đáp ứng liên tục, không ràng buộc đầu ra trong [0,1].","Cây phân loại cũng có thể trả xác suất theo tỷ lệ ở lá, nên phương án này không bất khả thi về kỹ thuật; A là đáp án dự kiến trong ngữ cảnh regression.","Luật kết hợp mô tả đồng xuất hiện thay vì mô hình xác suất có biến đích như câu hỏi."],"caution":"Câu hỏi rộng: decision trees cũng có thể dự đoán xác suất. A phù hợp nhất theo ngữ cảnh đoạn sách, không nên nhớ rằng chỉ logistic mới làm được.","topic":"Regression","gradable":true,"keyChanged":false,"bookPage":178,"pdfPage":198,"reference":"Sách chương 6, trang 178 (PDF trang 198) · Slide chương 6, slide 31, 34","slideNumbers":[31,34],"keywords":["predict the likelihood","input variables"]},{"id":30,"stem":"In logistic regression, deviance is defined to be ____, where L is the maximized value of the likelihood function used to obtain the parameter estimates.","options":["+2 × log L","−2 × log L","−3 × log L","−4 × log L"],"image":"assets/dta301/fa24/30.webp","suppliedKey":null,"multiple":false,"correct":[1],"chapter":6,"sourceTerm":"deviance","detail":"Theo cách trình bày logistic Bernoulli trong sách, deviance = −2 log L. Công thức tổng quát là −2 log(Lfitted/Lsaturated).","trick":"Deviance: âm hai log-likelihood.","why":["Sai dấu dương.","Đúng hệ số −2.","Sai hệ số −3.","Sai hệ số −4."],"caution":"Biểu thức rút gọn trong đề dùng chuẩn hóa với saturated likelihood. Khi so mô hình, dùng chênh lệch deviance hoặc tỷ số likelihood phù hợp.","topic":"Regression","gradable":true,"keyChanged":false,"bookPage":183,"pdfPage":203,"reference":"Sách chương 6, trang 183 (PDF trang 203) · Slide chương 6, slide 43, 44, 45","slideNumbers":[43,44,45],"keywords":["logistic regression","deviance","maximized"]},{"id":31,"stem":"In a decision tree, ____ are the decision or test points.","options":["Internal nodes","Splits","Branches","Leaf nodes"],"image":"assets/dta301/fa24/31.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":7,"sourceTerm":"internal nodes","detail":"Internal nodes là các điểm kiểm tra/ra quyết định trong cây.","trick":"Node hỏi – branch đi – leaf trả lời.","why":["Đúng nơi kiểm tra một thuộc tính/điều kiện.","Split là thao tác chia tập, không phải tên loại nút.","Branch là nhánh ứng với kết quả phép kiểm tra.","Leaf là nơi đưa ra dự đoán cuối."],"caution":"","topic":"Classification","gradable":true,"keyChanged":false,"bookPage":193,"pdfPage":213,"reference":"Sách chương 7, trang 193 (PDF trang 213) · Slide chương 7, slide 7","slideNumbers":[7],"keywords":["decision tree","decision or test points"]},{"id":32,"stem":"A naive Bayes classifier assumes that the presence or absence of a particular feature of a class is related to the presence or absence of other features?","options":["True","False"],"image":"assets/dta301/fa24/32.webp","suppliedKey":null,"multiple":false,"correct":[1],"chapter":7,"sourceTerm":"independent","detail":"Naive Bayes giả định các đặc trưng độc lập có điều kiện khi biết lớp.","trick":"Naive = độc lập khi biết class.","why":["Sai vì câu nói “related” trái với giả định độc lập có điều kiện.","Đúng: phát biểu trong đề sai."],"caution":"Độc lập có điều kiện theo class, không nhất thiết độc lập vô điều kiện trong toàn bộ dữ liệu.","topic":"Classification","gradable":true,"keyChanged":false,"bookPage":214,"pdfPage":234,"reference":"Sách chương 7, trang 214 (PDF trang 234) · Slide chương 7, slide 45","slideNumbers":[45],"keywords":["naive Bayes","feature","other features"]},{"id":33,"stem":"In decision tree, the top internal node is called the __","options":["root","leaf","split","node"],"image":"assets/dta301/fa24/33.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":7,"sourceTerm":"root","detail":"Nút trong cùng cao nhất của cây là root node.","trick":"Root ở đầu cây quyết định.","why":["Tên chính xác của nút đầu cây.","Leaf là nút lá cuối nhánh.","Split là phép chia.","Node quá chung, không xác định vị trí cao nhất."],"caution":"","topic":"Classification","gradable":true,"keyChanged":false,"bookPage":193,"pdfPage":213,"reference":"Sách chương 7, trang 193 (PDF trang 213) · Slide chương 7, slide 7, 8, 12","slideNumbers":[7,8,12],"keywords":["decision tree","top internal node"]},{"id":34,"stem":"Bayes’ theorem gives the relationship between the probabilities of two events and their ____.","options":["conditional probabilities","conditional confidence","conditional interval","Interval confidence","minimum support"],"image":"assets/dta301/fa24/34.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":7,"sourceTerm":"Bayes","detail":"Bayes liên hệ P(A|B) với P(B|A), P(A) và P(B).","trick":"Bayes đảo điều kiện A|B ↔ B|A.","why":["Đúng thuật ngữ xác suất có điều kiện.","Không phải thuật ngữ trong định lý Bayes.","Không phải mối quan hệ định lý này mô tả.","Confidence interval thuộc ước lượng khoảng.","Minimum support thuộc association rules."],"caution":"","topic":"Classification","gradable":true,"keyChanged":false,"bookPage":212,"pdfPage":232,"reference":"Sách chương 7, trang 212 (PDF trang 232) · Slide chương 7, slide 38","slideNumbers":[38],"keywords":["Bayes’ theorem","probabilities of two events"]},{"id":35,"stem":"Which algorithm introduces a number of improvements over the original ID3 algorithm?","options":["The C4.5","CART (or Classification And Regression Trees)","Naive Bayes","Decisions tree"],"image":"assets/dta301/fa24/35.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":7,"sourceTerm":"C4.5","detail":"C4.5 là thuật toán kế thừa và cải tiến ID3.","trick":"ID3 → C4.5.","why":["Đúng thuật toán cải tiến trực tiếp ID3.","CART là dòng thuật toán cây khác.","Naive Bayes là bộ phân loại xác suất.","Decision tree là tên họ mô hình, không phải thuật toán kế thừa cụ thể."],"caution":"","topic":"Classification","gradable":true,"keyChanged":false,"bookPage":203,"pdfPage":223,"reference":"Sách chương 7, trang 203 (PDF trang 223) · Slide chương 7, slide 25","slideNumbers":[25],"keywords":["improvements","original ID3"]},{"id":36,"stem":"Which model is expressed by yt = εt + θ1 ε(t−1) + … + θq ε(t−q), with θq ≠ 0 and white-noise εt?","options":["For a time series centered at zero, a moving average model of order q, denoted MA(q).","For a stationary time series, an autoregressive model of order p, denoted AR(p)."],"image":"assets/dta301/fa24/36.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":8,"sourceTerm":"moving average model","detail":"MA(q) biểu diễn yt theo nhiễu hiện tại và các nhiễu trễ ε(t−j). AR(p) dùng các giá trị yt trễ.","trick":"MA nhìn ε cũ; AR nhìn y cũ.","why":["Đúng vì bên phải là tổng các sai số ε.","AR cần các y(t−1), y(t−2)… thay vì chỉ các ε."],"caution":"","topic":"Time Series","gradable":true,"keyChanged":false,"bookPage":239,"pdfPage":259,"reference":"Sách chương 8, trang 239 (PDF trang 259) · Slide chương 8, slide 18","slideNumbers":[18],"keywords":["θ1 ε(t−1)","θq ε(t−q)","white-noise"]},{"id":37,"stem":"Which of the following is NOT a steps in Box-Jenkins methodology for time series analysis?","options":["1. Condition data and select a model.","2. Estimate the model parameters.","3. Assess the model and return to Step 1, if necessary.","4, Gain the result from model and return to Step 1, if necessary."],"image":"assets/dta301/fa24/37.webp","suppliedKey":null,"multiple":false,"correct":[3],"chapter":8,"sourceTerm":"Box","detail":"Box–Jenkins gồm chọn/nhận diện mô hình, ước lượng tham số, kiểm tra chẩn đoán và quay lại nếu cần.","trick":"Chọn – Ước lượng – Kiểm tra.","why":["Đúng bước chuẩn bị và nhận diện.","Đúng bước ước lượng.","Đúng bước chẩn đoán lặp lại nếu mô hình chưa đạt.","Không phải bước 4 riêng trong danh sách ba bước của tài liệu."],"caution":"","topic":"Time Series","gradable":true,"keyChanged":false,"bookPage":235,"pdfPage":255,"reference":"Sách chương 8, trang 235 (PDF trang 255) · Slide chương 8, slide 6","slideNumbers":[6],"keywords":["NOT","Box-Jenkins"]},{"id":38,"stem":"A time series yt is stationary if the following conditions are met, except:","options":["The expected value (mean) of yt is a constant for all values of t.","The variance of yt is finite","The covariance of y t and y t +h depends only on the value of h=0,1, 2, .. forall t.","The covariance of y t and y t +h not depends only on the value of h=0,1, 2, .. for all t."],"image":"assets/dta301/fa24/38.webp","suppliedKey":null,"multiple":false,"correct":[3],"chapter":8,"sourceTerm":"stationary time series","detail":"Chuỗi dừng yếu có mean không đổi, variance hữu hạn không đổi và covariance chỉ phụ thuộc độ trễ h.","trick":"Dừng: mean/variance ổn định; covariance theo lag.","why":["Mean không đổi là điều kiện đúng.","Variance phải hữu hạn, và đầy đủ hơn là không đổi theo t.","Covariance chỉ theo h là điều kiện đúng.","Phủ định tính phụ thuộc chỉ vào h, trái với điều kiện dừng."],"caution":"B được viết thiếu “không đổi”; variance chỉ hữu hạn chưa đủ để kết luận chuỗi dừng. D là phát biểu sai trực tiếp.","topic":"Time Series","gradable":true,"keyChanged":false,"bookPage":236,"pdfPage":256,"reference":"Sách chương 8, trang 236 (PDF trang 256) · Slide chương 8, slide 8","slideNumbers":[8],"keywords":["stationary","except"]},{"id":39,"stem":"Is the covariance correctly expressed by cov(yt, y(t+h)) = E[(yt − μt)(y(t+h) + μ(t+h))]?","options":["True","False"],"image":"assets/dta301/fa24/39.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":8,"sourceTerm":"covariance","detail":"Biểu thức trong ảnh vẫn bằng covariance nếu các moment tồn tại. Đặt X=yt, Y=y(t+h). Vì E[X−μX]=0 nên E[(X−μX)(Y+μY)] = E[(X−μX)Y] = E[XY]−μXμY = Cov(X,Y). Công thức chuẩn trong sách thường viết dấu trừ ở cả hai ngoặc, nhưng đổi dấu của hằng số ở ngoặc thứ hai không làm đổi kỳ vọng khi ngoặc thứ nhất đã được centered.","trick":"Một thừa số đã trừ mean → kỳ vọng của nó bằng 0 → cộng/trừ hằng số ở thừa số kia không đổi covariance.","why":["Đúng về đại số: phần thêm hằng số triệt tiêu vì E[X−μX]=0.","Không thể kết luận sai chỉ vì có dấu cộng; hai biểu thức kỳ vọng tương đương, dù cách viết khác công thức chuẩn."],"caution":"Đáp án theo nghĩa toán học: A. Nếu key chấm B chỉ vì dấu cộng, key đó đã bỏ qua việc E[yt−μt]=0. Đối chiếu công thức chuẩn ở sách và phân tích đại số, không học máy móc dấu.","topic":"Time Series","gradable":true,"keyChanged":false,"bookPage":236,"pdfPage":256,"reference":"Sách chương 8, trang 236 (PDF trang 256) · Slide chương 8, slide 8","slideNumbers":[8],"keywords":["covariance","(y(t+h) + μ(t+h))"]},{"id":40,"stem":"is a useful model for addressing time series with non-constant variance or volatility. It is used for modeling stock market activity and price fluctuations.","options":["Autoregressive Moving Average with Exogenous inputs (ARMAX)","Spectral analysis","Generalized Autoregressive Conditionally Heteroscedastic (GARCH)","Kalman filtering","Multivariate time series analysis"],"image":"assets/dta301/fa24/40.webp","suppliedKey":null,"multiple":false,"correct":[2],"chapter":8,"sourceTerm":"GARCH","detail":"GARCH mô hình hóa phương sai có điều kiện biến đổi và volatility, thường dùng cho tài chính.","trick":"GARCH = volatility/phương sai thay đổi.","why":["ARMAX thêm đầu vào ngoại sinh vào mô hình chuỗi.","Spectral analysis nghiên cứu thành phần tần số.","Đúng mô hình dành cho volatility thay đổi theo thời gian.","Kalman filter ước lượng trạng thái ẩn động.","Multivariate time series là mô hình nhiều chuỗi, không đặc trưng riêng cho volatility."],"caution":"","topic":"Time Series","gradable":true,"keyChanged":false,"bookPage":253,"pdfPage":273,"reference":"Sách chương 8, trang 253 (PDF trang 273) · Slide chương 8, slide 46","slideNumbers":[46],"keywords":["non-constant variance","volatility"]},{"id":41,"stem":"Which of the followings is the identification of the documents in a corpus that contain search items such as specific words, phrases, topics, or entities like people or organizations?","options":["Parsing","Search and retrieval","Text mining","Discover meaningful insights"],"image":"assets/dta301/fa24/41.webp","suppliedKey":null,"multiple":false,"correct":[1],"chapter":9,"sourceTerm":"Search and retrieval","detail":"Search and retrieval xác định tài liệu trong corpus chứa từ, cụm từ, chủ đề hoặc thực thể cần tìm.","trick":"Tìm tài liệu nào chứa từ = retrieval.","why":["Parsing tạo cấu trúc từ văn bản.","Đúng nhiệm vụ nhận diện tài liệu liên quan.","Text mining khai thác quan hệ/mẫu từ các biểu diễn đã tạo.","Đây là mục tiêu chung, không phải tên bước truy tìm tài liệu."],"caution":"","topic":"Text Analysis","gradable":true,"keyChanged":false,"bookPage":257,"pdfPage":277,"reference":"Sách chương 9, trang 257 (PDF trang 277) · Slide chương 9, slide 6, 48","slideNumbers":[6,48],"keywords":["identification of the documents","search items"]},{"id":42,"stem":"Which provides tools to automatically organize, search, understand, and summarize from vast amounts of information?","options":["Topic modeling","Case folding","Parsing","Search and retrieve","Normalization"],"image":"assets/dta301/fa24/42.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":9,"sourceTerm":"Topic modeling provides","detail":"Topic modeling tìm chủ đề ẩn và dùng chúng để tổ chức, tìm kiếm, hiểu, tóm tắt tập tài liệu.","trick":"Nhiều tài liệu → chủ đề ẩn → Topic modeling.","why":["Đúng mô tả trong sách.","Case folding chỉ chuẩn hóa chữ hoa/thường.","Parsing tạo cấu trúc biểu diễn.","Search and retrieval tập trung tìm tài liệu, không tự nó là mô hình chủ đề.","Normalization chuẩn hóa dạng từ/văn bản, không khám phá chủ đề."],"caution":"","topic":"Text Analysis","gradable":true,"keyChanged":false,"bookPage":267,"pdfPage":287,"reference":"Sách chương 9, trang 267 (PDF trang 287) · Slide chương 9, slide 26","slideNumbers":[26],"keywords":["automatically organize","search, understand, and summarize"]},{"id":43,"stem":"Which of the following techniques usually refers to a crude process of stripping affixes based on a set of heuristics with the hope of correctly achieving the goal to reduce inflections or variant forms?","options":["Lemmatization methods","Stemming methods","Classification methods","Clustering methods"],"image":"assets/dta301/fa24/43.webp","suppliedKey":null,"multiple":false,"correct":[1],"chapter":9,"sourceTerm":"stripping affixes","detail":"Stemming cắt tiền tố/hậu tố theo heuristic, không nhất thiết tạo từ đúng từ điển.","trick":"Stem = cắt gốc; Lemma = tra từ điển.","why":["Lemmatization dùng từ điển/ngữ pháp để tìm base form đúng.","Đúng mô tả stripping affixes bằng heuristic.","Classification gán nhãn.","Clustering gom nhóm."],"caution":"","topic":"Text Analysis","gradable":true,"keyChanged":false,"bookPage":258,"pdfPage":278,"reference":"Sách chương 9, trang 258 (PDF trang 278) · Slide chương 9, slide 8","slideNumbers":[8],"keywords":["stripping affixes","heuristics"]},{"id":44,"stem":"Which of the following represents the weight of each term in a document, and it is proportional to the number of occurrences of the term in that document?","options":["Information content (IC)","Term frequency (TF)","Inverse Document Frequency (IDF)","Document Frequency (DF)"],"image":"assets/dta301/fa24/44.webp","suppliedKey":null,"multiple":false,"correct":[1],"chapter":9,"sourceTerm":"term frequency","detail":"TF đo số lần một term xuất hiện trong một tài liệu, có thể được chuẩn hóa.","trick":"TF: Tần suất trong 1 File.","why":["IC là độ thông tin/độ quan trọng xét theo corpus và ontology.","Đúng trọng số dựa trên số lần xuất hiện trong tài liệu.","IDF giảm khi từ xuất hiện ở nhiều tài liệu.","DF đếm số tài liệu chứa từ, không đếm số lần trong một tài liệu."],"caution":"","topic":"Text Analysis","gradable":true,"keyChanged":false,"bookPage":265,"pdfPage":285,"reference":"Sách chương 9, trang 265 (PDF trang 285) · Slide chương 9, slide 3, 15, 17","slideNumbers":[3,15,17],"keywords":["weight of each term","number of occurrences"]},{"id":45,"stem":"Which is a metric to denote the importance of a term in a corpus?","options":["Information content (IC)","Term frequency (TF)","Inverse Document Frequency (IDF)","Document Frequency (DF)"],"image":"assets/dta301/fa24/45.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":9,"sourceTerm":"Information content","detail":"Sách định nghĩa Information Content (IC) là chỉ số biểu diễn mức quan trọng của một term trong corpus.","trick":"“importance of a term in a corpus” đúng câu định nghĩa IC.","why":["Đúng định nghĩa nguyên tắc trong mục Collecting Raw Text.","TF chỉ nhìn tần suất trong một tài liệu.","IDF cũng góp phần đo độ đặc trưng/quan trọng nhưng đây không phải thuật ngữ trong câu định nghĩa được trích.","DF là số tài liệu chứa term."],"caution":"Câu này phụ thuộc cách dùng từ của sách. Không suy ra IDF không liên quan đến độ quan trọng của term.","topic":"Text Analysis","gradable":true,"keyChanged":false,"bookPage":268,"pdfPage":288,"reference":"Sách chương 9, trang 268 (PDF trang 288) · Slides chương 9","slideNumbers":[],"keywords":["importance of a term","corpus"]},{"id":46,"stem":"The figure illustrates MapReduce processing for a single input. Step 1 splits a string into word/count pairs and Step 2 consolidates the intermediate output. Step 1 is ____; Step 2 is ____.","options":["Map / Reduce","Reduce / Map","MapReduce / Shuffle and Sort"],"image":"assets/dta301/fa24/46.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":10,"sourceTerm":"MapReduce processing","detail":"Map tạo các cặp trung gian theo từng đầu vào; Reduce tổng hợp chúng thành kết quả.","trick":"Map chia/xử lý; Reduce gom/tổng hợp.","why":["Đúng thứ tự hai giai đoạn trong hình.","Đảo ngược thứ tự.","Shuffle/sort nằm giữa map và reduce; không khớp hai bước được đánh dấu."],"caution":"","topic":"MapReduce và Hadoop","gradable":true,"keyChanged":false,"bookPage":298,"pdfPage":318,"reference":"Sách chương 10, trang 298 (PDF trang 318) · Slides chương 10","slideNumbers":[],"keywords":["Step 1 splits","Step 2 consolidates"]},{"id":47,"stem":"What step in MapReduce applies an operation to a piece of data?","options":["Map","Reduce","Parsing"],"image":"assets/dta301/fa24/47.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":10,"sourceTerm":"applies an operation","detail":"Map áp dụng phép xử lý cho từng phần dữ liệu đầu vào.","trick":"Map xử lý từng mảnh, Reduce gom kết quả.","why":["Đúng bước thao tác trên mỗi phần dữ liệu.","Reduce hợp nhất kết quả trung gian theo key.","Parsing là phân tích cú pháp/văn bản, không phải giai đoạn MapReduce đang hỏi."],"caution":"","topic":"MapReduce và Hadoop","gradable":true,"keyChanged":false,"bookPage":298,"pdfPage":318,"reference":"Sách chương 10, trang 298 (PDF trang 318) · Slide chương 10, slide 6","slideNumbers":[6],"keywords":["MapReduce","applies an operation"]},{"id":48,"stem":"MapReduce paradigm provides the means to break a large task into smaller tasks, run the tasks in sequence, and consolidate the outputs of the indi idual tasks into the final output?","options":["True","False"],"image":"assets/dta301/fa24/48.webp","suppliedKey":null,"multiple":false,"correct":[1],"chapter":10,"sourceTerm":"parallel","detail":"MapReduce chia công việc thành nhiều task để thực hiện song song; câu nói “in sequence” sai.","trick":"Bẫy sequence → phải là parallel.","why":["Sai vì thay song song bằng tuần tự.","Đúng: phát biểu bị sai ở cách thực thi các task."],"caution":"Trong một job, các giai đoạn vẫn có phụ thuộc; ý sai là nói các task được chạy tuần tự thay vì tận dụng song song.","topic":"MapReduce và Hadoop","gradable":true,"keyChanged":false,"bookPage":292,"pdfPage":312,"reference":"Sách chương 10, trang 292 (PDF trang 312) · Slide chương 10, slide 5, 6, 10","slideNumbers":[5,6,10],"keywords":["MapReduce","run the tasks in sequence"]},{"id":49,"stem":"In Apache Hadoop, ____ provides the logic to be processed on each data block corresponding to the specified input files in the driver code.","options":["The driver","The mapper","The scheduler","The combiner"],"image":"assets/dta301/fa24/49.webp","suppliedKey":null,"multiple":false,"correct":[1],"chapter":10,"sourceTerm":"mapper","detail":"Mapper cung cấp logic xử lý đầu vào/block được chỉ định bởi driver.","trick":"Driver chỉ đường; Mapper làm việc.","why":["Driver cấu hình job và tên các lớp/đường dẫn.","Đúng nơi cài logic map.","Scheduler phân phối lịch tài nguyên/task.","Combiner tổng hợp cục bộ đầu ra map khi thích hợp."],"caution":"","topic":"MapReduce và Hadoop","gradable":true,"keyChanged":false,"bookPage":301,"pdfPage":321,"reference":"Sách chương 10, trang 301 (PDF trang 321) · Slide chương 10, slide 14, 17","slideNumbers":[14,17],"keywords":["Hadoop","logic","each data block"]},{"id":50,"stem":"In the Apache Hadoop, provides details such as input file locations, the provisions for adding the input file to the map task, the names of the mapper and reducer Java classes, and the location of the reduce task output.","options":["The driver","The mapper","The scheduler","The broker"],"image":"assets/dta301/fa24/50.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":10,"sourceTerm":"driver","detail":"Driver khai báo đầu vào, mapper/reducer classes và vị trí đầu ra của job.","trick":"Driver = cấu hình hành trình job.","why":["Đúng vai trò cấu hình và khởi chạy job.","Mapper xử lý từng record/phần dữ liệu.","Scheduler điều phối tài nguyên thực thi.","Broker không phải thành phần đang được định nghĩa."],"caution":"","topic":"MapReduce và Hadoop","gradable":true,"keyChanged":false,"bookPage":301,"pdfPage":321,"reference":"Sách chương 10, trang 301 (PDF trang 321) · Slide chương 10, slide 14, 20","slideNumbers":[14,20],"keywords":["input file locations","mapper and reducer","reduce task output"]},{"id":51,"stem":"The following statement will return: SELECT '123a567' ~ '2...5';","options":["True","False","Error","Empty"],"image":"assets/dta301/fa24/51.webp","suppliedKey":null,"multiple":false,"correct":[1],"chapter":11,"sourceTerm":"Regular Expressions","detail":"Pattern 2...5 cần ba ký tự giữa 2 và 5. Chuỗi 123a567 chỉ có hai ký tự 3,a giữa 2 và 5 nên không khớp.","trick":"Đếm dấu chấm: mỗi . đúng 1 ký tự.","why":["Không có đoạn con khớp 2 + ba ký tự + 5.","Đúng kết quả boolean false.","Cú pháp toán tử ~ và regex này hợp lệ.","~ trả boolean, không trả tập rỗng."],"caution":"","topic":"SQL và công cụ","gradable":true,"keyChanged":false,"bookPage":340,"pdfPage":360,"reference":"Sách chương 11, trang 340 (PDF trang 360) · Slide chương 11, slide 13","slideNumbers":[13],"keywords":["SELECT","'2...5'"]},{"id":52,"stem":"The following statement will return: SELECT '123a567' ~ '23|b';","options":["True","False","Error","Nothing"],"image":"assets/dta301/fa24/52.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":11,"sourceTerm":"Regular Expressions","detail":"Dấu | là OR. Pattern 23|b khớp chuỗi vì có đoạn con 23.","trick":"Regex | = hoặc; ~ không yêu cầu khớp cả chuỗi.","why":["Đúng vì có 23.","Không cần có cả 23 và b; chỉ một nhánh khớp là đủ.","Regex luân phiên này hợp lệ.","Kết quả của ~ là true/false, không phải Nothing."],"caution":"","topic":"SQL và công cụ","gradable":true,"keyChanged":false,"bookPage":340,"pdfPage":360,"reference":"Sách chương 11, trang 340 (PDF trang 360) · Slide chương 11, slide 13","slideNumbers":[13],"keywords":["SELECT","'23|b'"]},{"id":53,"stem":"____ function can be used to order a set of rows based on some attribute.","options":["RANK()","Order()","Sort()","Having()"],"image":"assets/dta301/fa24/53.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":11,"sourceTerm":"RANK()","detail":"RANK() OVER (ORDER BY ...) tạo thứ hạng theo thuộc tính. Câu dùng “order” theo nghĩa xếp hạng trong mục Window Functions.","trick":"RANK xếp hạng; ORDER BY sắp thứ tự kết quả.","why":["Đúng window function mà sách nêu trong đoạn này.","SQL dùng mệnh đề ORDER BY, không có Order() như phương án.","Sort() không phải hàm PostgreSQL được hỏi.","HAVING là mệnh đề lọc nhóm, không phải hàm xếp hạng."],"caution":"RANK không tự đảm bảo thứ tự hiển thị của toàn bộ kết quả SQL; muốn sắp kết quả cần ORDER BY ở truy vấn ngoài.","topic":"SQL và công cụ","gradable":true,"keyChanged":false,"bookPage":343,"pdfPage":363,"reference":"Sách chương 11, trang 343 (PDF trang 363) · Slide chương 11, slide 19, 20","slideNumbers":[19,20],"keywords":["order a set of rows","attribute"]},{"id":54,"stem":"Which of the following function in PostgreSQL rank of the current row without gaps? This function counts peer groups.","options":["rank()","dense_rank()","percent_rank()","row_number()"],"image":"assets/dta301/fa24/54.webp","suppliedKey":null,"multiple":false,"correct":[1],"chapter":11,"sourceTerm":"dense_rank","detail":"DENSE_RANK cho thứ hạng không bỏ số sau các giá trị đồng hạng.","trick":"DENSE = dày liền: 1,1,2; RANK: 1,1,3.","why":["RANK có khoảng trống sau đồng hạng.","Đúng không gaps, đếm peer groups.","PERCENT_RANK là thứ hạng tương đối.","ROW_NUMBER đánh số riêng cho từng dòng, không cùng hạng cho peers."],"caution":"","topic":"SQL và công cụ","gradable":true,"keyChanged":false,"bookPage":347,"pdfPage":367,"reference":"Sách chương 11, trang 347 (PDF trang 367) · Slides chương 11","slideNumbers":[],"keywords":["PostgreSQL","without gaps","peer groups"]},{"id":55,"stem":"The following statement will return: SELECT '123a567' ~ '2\\*';","options":["True","False","Error","Empty"],"image":"assets/dta301/fa24/55.webp","suppliedKey":null,"multiple":false,"correct":[1],"chapter":11,"sourceTerm":"Regular Expressions","detail":"Trong ảnh, pattern là 2\\*: dấu \\ escape làm * thành ký tự literal. Chuỗi không chứa 2* nên false.","trick":"\\* = dấu sao thật; * trần = lặp 0 hoặc nhiều.","why":["Chỉ đúng nếu pattern là 2* không escape, hoặc chuỗi chứa literal 2*.","Đúng vì không có đoạn 2*.","Regex escape dấu sao là hợp lệ với cấu hình standard_conforming_strings mặc định.","~ trả boolean, không trả Empty."],"caution":"Giữ nguyên dấu backslash trong ảnh. Cách diễn giải dùng cấu hình PostgreSQL standard_conforming_strings mặc định on; thay cấu hình chuỗi có thể thay cách xử lý backslash.","topic":"SQL và công cụ","gradable":true,"keyChanged":false,"bookPage":340,"pdfPage":360,"reference":"Sách chương 11, trang 340 (PDF trang 360) · Slide chương 11, slide 13","slideNumbers":[13],"keywords":["SELECT","'2\\*'"]},{"id":56,"stem":"In the Approach section of presentations for Analyst, we should discuss on","options":["High-level methodology","High-level methodology, Relevant details on modeling techniques and technology","Emphasize key messages","Overview of the modeling technique"],"image":"assets/dta301/fa24/56.webp","suppliedKey":null,"multiple":false,"correct":[1],"chapter":12,"sourceTerm":"Relevant details on modeling","detail":"Approach cho Analyst cần cả phương pháp tổng quan và chi tiết liên quan về kỹ thuật mô hình/công nghệ.","trick":"Analyst hỏi thêm “làm thế nào và bằng gì?”.","why":["Chỉ phần tổng quan, phù hợp sponsor nhưng thiếu độ sâu cho analyst.","Đủ hai thành phần theo bảng 12-1.","Đây là Main Findings.","Đây là Model Description."],"caution":"","topic":"Báo cáo và triển khai","gradable":true,"keyChanged":false,"bookPage":365,"pdfPage":385,"reference":"Sách chương 12, trang 365 (PDF trang 385) · Slides chương 12","slideNumbers":[],"keywords":["Approach section","Analyst"]},{"id":57,"stem":"Who needs to know if the reports and dashboards he manages will be impacted and need to change at the conclusion of a project?","options":["Data Scientists","Data Engineer and Database Administrator (DBA)","Business Intelligence Analyst","Project Manager"],"image":"assets/dta301/fa24/57.webp","suppliedKey":null,"multiple":false,"correct":[2],"chapter":12,"sourceTerm":"reports and dashboards","detail":"BI Analyst cần biết báo cáo/dashboard họ quản lý có bị tác động và cần thay đổi không.","trick":"BI = báo cáo/dashboard.","why":["Data Scientist giải thích mô hình và chia sẻ code.","Engineer/DBA chú trọng triển khai code, dữ liệu và hạ tầng.","Đúng người quản lý báo cáo và dashboard.","Project Manager chú trọng tiến độ, ngân sách."],"caution":"","topic":"Báo cáo và triển khai","gradable":true,"keyChanged":false,"bookPage":362,"pdfPage":382,"reference":"Sách chương 12, trang 362 (PDF trang 382) · Slides chương 12","slideNumbers":[],"keywords":["reports and dashboards","impacted"]},{"id":58,"stem":"Who typically tries to determine the benefits and implications of key project outputs of the findings to ‘the Business?","options":["Business users.","Project sponsor","Business Intelligence analyst","Data Scientists"],"image":"assets/dta301/fa24/58.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":12,"sourceTerm":"benefits and implications","detail":"Business User quan tâm kết quả đem lại lợi ích và tác động gì cho nghiệp vụ.","trick":"User dùng kết quả; Sponsor xét ROI.","why":["Đúng mô tả Business User trong sách.","Sponsor chú trọng business impact, rủi ro và ROI.","BI Analyst xem tác động lên báo cáo/dashboard.","Data Scientist giải thích mô hình và code."],"caution":"","topic":"Báo cáo và triển khai","gradable":true,"keyChanged":false,"bookPage":361,"pdfPage":381,"reference":"Sách chương 12, trang 361 (PDF trang 381) · Slide chương 12, slide 6","slideNumbers":[6],"keywords":["benefits and implications","Business"]},{"id":59,"stem":"Who typically need to share the code from the analytical project and create technical documents that describe how to implement the code at the conclusion of a project?","options":["Data Engineer and Database Administrator (DBA)","Business Intelligence Analyst","Project Manager","Business User"],"image":"assets/dta301/fa24/59.webp","suppliedKey":null,"multiple":false,"correct":[0],"chapter":12,"sourceTerm":"technical documents","detail":"Data Engineer và DBA cần chia sẻ code cùng tài liệu kỹ thuật mô tả cách triển khai.","trick":"Engineer/DBA = code chạy được + hướng dẫn triển khai.","why":["Đúng vai trò trong mục key outputs.","BI Analyst quan tâm báo cáo/dashboard.","Project Manager đánh giá tiến độ/ngân sách.","Business User quan tâm lợi ích nghiệp vụ."],"caution":"","topic":"Báo cáo và triển khai","gradable":true,"keyChanged":false,"bookPage":362,"pdfPage":382,"reference":"Sách chương 12, trang 362 (PDF trang 382) · Slides chương 12","slideNumbers":[],"keywords":["share the code","technical documents"]},{"id":60,"stem":"Which of the following section in of presentations for Project Sponsor we should discuss on overview of the modeling technique used in data analytics project?","options":["Key Points Supported with Data","Model Details","Model Description","Main Findings"],"image":"assets/dta301/fa24/60.webp","suppliedKey":null,"multiple":false,"correct":[2],"chapter":12,"sourceTerm":"Model Description","detail":"Model Description cung cấp tổng quan kỹ thuật mô hình cho sponsor.","trick":"Description = mô tả tổng quan; Details = đào sâu.","why":["Key Points Supported with Data dùng biểu đồ hỗ trợ luận điểm.","Model Details có thể lược bỏ hoặc chỉ nói mức cao với sponsor.","Đúng phần overview of modeling technique.","Main Findings nhấn mạnh thông điệp/phát hiện chính."],"caution":"","topic":"Báo cáo và triển khai","gradable":true,"keyChanged":false,"bookPage":365,"pdfPage":385,"reference":"Sách chương 12, trang 365 (PDF trang 385) · Slide chương 12, slide 20, 21","slideNumbers":[20,21],"keywords":["Project Sponsor","overview of the modeling technique"]}],"subject":"dta301","legacyExamId":"fa24"}});